"""Pending-authority bounded trial support. Import performs no inference or network."""
import asyncio
import hashlib
import json
import os
import socket
from contextvars import ContextVar
from dataclasses import asdict
from datetime import UTC, datetime
from pathlib import Path

import httpx
import httpx2

from distill.config import DistillConfig
from distill.library.paths import atomic_write_json, atomic_write_text
from distill.llm import call
from distill.llm.cost import get_pricing, has_known_pricing
from distill.llm.providers.ollama import OllamaProvider
from distill.llm.router import RouterConfig
from distill.pipeline.costs import CostTracker, TokenUsage

ROOT = Path('.agent/issue61-67-third-trial').resolve()
AUTHORITY = Path('.agent/third-trial-authority.json')
LOCAL = 'qwen3.6:27b'
CLOUD = 'anthropic/claude-sonnet-5.5'


class ThirdTrial:
    def __init__(self):
        self.authority = json.loads(AUTHORITY.read_text())
        self.deadline = datetime.fromisoformat(self.authority['deadline_utc'])
        started = datetime.fromisoformat(self.authority['started_at'])
        if not 0 < (self.deadline - started).total_seconds() <= 1800:
            raise ValueError('Authority exceeds 30-minute scope')
        self.cloud_allowed = self.authority.get('cloud_allowed') is True
        if self.authority.get('max_attempts') != 30 or self.authority.get('budget_usd') != 3:
            raise ValueError('Unexpected authority bounds')
        ROOT.mkdir(parents=True, exist_ok=True)
        path = ROOT / 'trial.json'
        self.receipt = json.loads(path.read_text()) if path.exists() else {
            'schema': 'bounded-third-trial.v1', 'authority': self.authority,
            'attempts': [], 'calls': [], 'cost_entries': [], 'models': {},
            'status': 'in_progress', 'defaults_changed': False,
            'source_contract': 'public_or_synthetic_only_no_private_corpus',
            'limits': {'attempts': 30, 'seconds': 1800, 'usd': 3,
                       'output_tokens': 4096, 'prompt_utf8_bytes': 48000},
        }
        if self.receipt['authority'] != self.authority:
            raise ValueError('Cannot resume under changed authority')
        if any(row['status'] == 'started' for row in self.receipt['calls']):
            raise ValueError('Interrupted call has unresolved usage; reconcile before resuming')
        self.tracker = CostTracker(budget=3)
        for row in self.receipt['cost_entries']:
            self.tracker.record(TokenUsage(**row))
        self.secret = DistillConfig().openrouter_api_key.get_secret_value() if self.cloud_allowed else ''
        if self.cloud_allowed and not self.secret:
            raise ValueError('Approved cloud route has no configured key')
        self.guard()
        self.install_transport_counter()
        self.save()

    def left(self):
        left = (self.deadline - datetime.now(UTC)).total_seconds()
        if left <= 0:
            raise TimeoutError('Trial authority expired')
        return min(left, 60)

    def save(self):
        self.receipt['cost_entries'] = [asdict(row) for row in self.tracker.entries]
        self.receipt['updated_at'] = datetime.now(UTC).isoformat()
        atomic_write_json(ROOT / 'trial.json', self.receipt)

    def guard(self):
        original_dns = socket.getaddrinfo
        allowed_ips = set()
        if self.cloud_allowed:
            allowed_ips = {row[4][0] for row in original_dns('openrouter.ai', 443, type=socket.SOCK_STREAM)}
        original_connect, original_connect_ex = socket.socket.connect, socket.socket.connect_ex
        original_pair = socket.socketpair
        control = ContextVar('third_trial_control_pair', default=False)

        def dns(host, port, *args, **kwargs):
            if host not in ('127.0.0.1', '::1', 'localhost', 'openrouter.ai'):
                raise OSError('Trial DNS host denied')
            if host == 'openrouter.ai' and (not self.cloud_allowed or str(port) != '443'):
                raise OSError('Cloud DNS not authorized')
            return original_dns(host, port, *args, **kwargs)

        def pair(*args, **kwargs):
            token = control.set(True)
            try:
                return original_pair(*args, **kwargs)
            finally:
                control.reset(token)

        def wrap(original):
            def connect(sock, address):
                local = isinstance(address, tuple) and address[0] in ('127.0.0.1', '::1')
                cloud = isinstance(address, tuple) and address[0] in allowed_ips and address[1] == 443
                if not ((local and (address[1] == 11434 or control.get())) or cloud):
                    raise OSError('Trial network route denied')
                return original(sock, address)
            return connect

        socket.getaddrinfo = dns
        socket.socketpair = pair
        socket.socket.connect = wrap(original_connect)
        socket.socket.connect_ex = wrap(original_connect_ex)
        for name in list(os.environ):
            if name.endswith(('_API_KEY', '_TOKEN', '_PASSWORD', '_SECRET')):
                os.environ.pop(name, None)
        for name in ('HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY', 'http_proxy', 'https_proxy', 'all_proxy'):
            os.environ.pop(name, None)
        os.environ.update(OLLAMA_BASE_URL='http://127.0.0.1:11434', HF_HUB_OFFLINE='1', TRANSFORMERS_OFFLINE='1')
        for tag in ('ANALYSIS', 'SITE', 'QA', 'RERANK'):
            os.environ.pop(f'DISTILL_{tag}_REASONING_EFFORT', None)
            os.environ.pop(f'DISTILL_{tag}_LOCAL_THINK', None)

    def install_transport_counter(self):
        trial = self

        def begin(request):
            if request.method != 'POST' or request.url.path not in ('/api/chat', '/api/v1/chat/completions'):
                return None
            trial.left()
            if len(trial.receipt['attempts']) >= 30:
                raise ValueError('Actual provider attempt cap exhausted')
            payload = json.loads(request.content)
            model = payload.get('model')
            local = request.url.host == '127.0.0.1' and model == LOCAL
            cloud = trial.cloud_allowed and request.url.host == 'openrouter.ai' and model == CLOUD
            if not (local or cloud) or payload.get('tools'):
                raise ValueError('Unapproved inference payload')
            limit = payload.get('max_tokens', payload.get('max_completion_tokens', payload.get('options', {}).get('num_predict', 0)))
            if type(limit) is not int or not 1 <= limit <= 4096:
                raise ValueError('Output token bound exceeded')
            if sum(len(message.get('content', '').encode()) for message in payload.get('messages', []) if isinstance(message.get('content'), str)) > 48000:
                raise ValueError('Payload prompt byte bound exceeded')
            if cloud and any(message.get('images') or not isinstance(message.get('content'), str) for message in payload.get('messages', [])):
                raise ValueError('Cloud route is text-only')
            for message in payload.get('messages', []):
                message.pop('thinking', None)
            canonical = json.dumps(payload, sort_keys=True, separators=(',', ':'))
            digest = hashlib.sha256(canonical.encode()).hexdigest()
            atomic_write_text(ROOT / 'requests' / f'{digest}.json', canonical)
            row = {'attempt': len(trial.receipt['attempts']) + 1, 'model': model,
                   'payload_sha256': digest, 'started_at': datetime.now(UTC).isoformat(), 'status': 'submitted'}
            trial.receipt['attempts'].append(row)
            trial.save()
            return row

        def send(client, request, *, _original, **kwargs):
            row = begin(request)
            try:
                response = _original(client, request, **kwargs)
                if row is not None:
                    row.update(http_status=response.status_code, status='http_response')
                return response
            except Exception as exc:
                if row is not None:
                    row.update(status='transport_error', error_type=type(exc).__name__)
                raise
            finally:
                trial.save()

        async def asend(client, request, *, _original, **kwargs):
            row = begin(request)
            try:
                response = await _original(client, request, **kwargs)
                if row is not None:
                    row.update(http_status=response.status_code, status='http_response')
                return response
            except Exception as exc:
                if row is not None:
                    row.update(status='transport_error', error_type=type(exc).__name__)
                raise
            finally:
                trial.save()

        # The locked OpenAI SDK uses httpx2, while Ollama uses httpx. Count at
        # each library's single-request dispatch so SDK calls and redirects
        # cannot bypass the shared cap. Bind originals separately for each.
        for library in (httpx, httpx2):
            original_sync = library.Client._send_single_request
            original_async = library.AsyncClient._send_single_request

            def sync_dispatch(client, request, _original=original_sync):
                return send(client, request, _original=_original)

            async def async_dispatch(client, request, _original=original_async):
                return await asend(client, request, _original=_original)

            library.Client._send_single_request = sync_dispatch
            library.AsyncClient._send_single_request = async_dispatch
        async def context(provider, model, prompt, max_tokens):
            if model != LOCAL or await provider.get_context_window(model) < 32768:
                raise ValueError('Unexpected local model context')
            return 32768
        OllamaProvider._adaptive_num_ctx = context

    def prove_local(self):
        with httpx.Client(timeout=self.left(), trust_env=False) as client:
            tags = client.get('http://127.0.0.1:11434/api/tags').json()
        entry = next(row for row in tags['models'] if row.get('name') == LOCAL)
        previous = self.receipt['models'].get(LOCAL)
        if previous and previous['digest'] != entry['digest']:
            raise ValueError('Local model digest changed')
        asyncio.run(OllamaProvider('http://127.0.0.1:11434').require_local(LOCAL))
        self.receipt['models'][LOCAL] = {'digest': entry['digest'], 'local_proof': 'fresh_passed'}

    def verify_catalog(self):
        with httpx.Client(timeout=self.left(), trust_env=False) as client:
            response = client.get('https://openrouter.ai/api/v1/models')
            response.raise_for_status()
            catalog = response.json()
        model = next(row for row in catalog['data'] if row['id'] == CLOUD)
        if float(model['pricing']['prompt']) != 0.000002 or float(model['pricing']['completion']) != 0.00001:
            raise ValueError('Public catalog prices changed; stop for scope review')
        if not has_known_pricing(CLOUD) or get_pricing(CLOUD) != {'input': 2.0, 'output': 10.0}:
            raise ValueError('Canonical registered prices do not match reviewed public prices')
        self.receipt['models'][CLOUD] = model
        atomic_write_json(ROOT / 'public-sonnet-model-catalog.json', model)

    def config_for(self, provider):
        if provider == 'ollama':
            self.prove_local()
            return RouterConfig(provider='ollama', model=LOCAL, site_provider='ollama', site_model=LOCAL,
                                analysis_provider='ollama', qa_provider='ollama', rerank_provider='ollama',
                                cost_mode='no-metered', fallback_provider='', fallback_model='')
        if provider != 'openrouter' or not self.cloud_allowed:
            raise ValueError('Cloud not explicitly authorized')
        self.verify_catalog()
        return RouterConfig(provider='openrouter', model=CLOUD, site_provider='openrouter', site_model=CLOUD,
                            analysis_provider='openrouter', qa_provider='openrouter', rerank_provider='openrouter',
                            openrouter_api_key=self.secret, cost_mode='paid-ok',
                            fallback_provider='', fallback_model='')

    def bounded_call(self, config, workload_tag, prompt, **kwargs):
        self.left()
        if len(prompt.encode()) > 48000:
            raise ValueError('Prompt exceeds declared byte ceiling; do not truncate')
        provider, model = config.resolve(workload_tag)
        if (provider, model) not in {('ollama', LOCAL), ('openrouter', CLOUD)}:
            raise ValueError('Unapproved model')
        if config.fallback_provider or config.fallback_model:
            raise ValueError('Fallback forbidden')
        if provider == 'openrouter' and (not self.cloud_allowed or kwargs.get('images')):
            raise ValueError('Cloud payload outside authority')
        if provider == 'ollama':
            self.prove_local()
        digest = hashlib.sha256(prompt.encode()).hexdigest()
        atomic_write_text(ROOT / 'prompts' / f'{digest}.txt', prompt)
        row = {'prompt_sha256': digest, 'provider': provider, 'model': model, 'status': 'started'}
        self.receipt['calls'].append(row)
        kwargs.update(max_tokens=min(kwargs.get('max_tokens', 4096), 4096), timeout=max(1, int(self.left())),
                      retries=0, temperature=0, usage_tracker=self.tracker)
        try:
            response = call(config, workload_tag, prompt, **kwargs)
            self.tracker.record(TokenUsage.from_response(response, call_type=kwargs.get('call_type', '')))
            row.update(status='completed', response=asdict(response))
            return response
        except Exception as exc:
            row.update(status='failed', error_type=type(exc).__name__)
            raise
        finally:
            self.save()
